from __future__ import annotations
from fractions import Fraction

def audit(n: int, k: int, d: int) -> dict[str, Fraction | int]:
    if min(n, k) < 0 or d <= 0 or k + 2 * (d - 1) > n:
        raise ValueError("inadmissible parameters")
    D, G = n + 2 - 2*d, n - 2*d
    assert 0 <= k <= D and D == G + 2
    return {"D": D, "G": G, "rate": Fraction(k,n), "ceiling": Fraction(D,n)}

if __name__ == "__main__":
    for row in [(20,2,10),(24,6,10),(40,22,10)]: print(row, audit(*row))

from __future__ import annotations

def bounded_family(B: int, sizes: list[int]) -> None:
    for n in sizes:
        ceiling = (B + 2) / n
        print(f"n={n:6d}, rate and entropy-density ceiling={ceiling:.8f}")

if __name__ == "__main__":
    bounded_family(4, [24, 204, 2004, 20004])

from __future__ import annotations
from fractions import Fraction

def positive_rate_test(n: int, k: int, d: int, epsilon: Fraction) -> bool:
    if n <= 0 or k + 2*(d-1) > n or epsilon > Fraction(k,n):
        return False
    return epsilon <= Fraction(n + 2 - 2*d, n)

if __name__ == "__main__":
    print(positive_rate_test(400, 202, 100, Fraction(2,5)))

