from __future__ import annotations
from dataclasses import dataclass
from fractions import Fraction
@dataclass(frozen=True)
class Audit:
    exact: int; geometric: int; rate: Fraction; ceiling: Fraction
def singleton_audit(n: int, k: int, d: int) -> Audit:
    if n <= 0 or k < 0 or d <= 0: raise ValueError("invalid domain")
    if k + 2*(d-1) > n: raise ValueError("Singleton violation")
    D, G = n + 2 - 2*d, n - 2*d
    assert D == G + 2 and 0 <= k <= D
    return Audit(D, G, Fraction(k,n), Fraction(D,n))

from __future__ import annotations
from typing import Iterable
def family_envelopes(rows: Iterable[tuple[int,int,int]], B: int) -> list[tuple[int,float]]:
    out: list[tuple[int,float]] = []
    for n,k,d in rows:
        if n <= 0 or d <= 0 or k < 0 or k+2*(d-1)>n: raise ValueError("inadmissible")
        if n-2*d > B: raise ValueError("G exceeds B")
        assert k <= B+2
        out.append((n,(B+2)/n))
    return out

from __future__ import annotations
from fractions import Fraction
def required_defect_density(n: int, k: int, d: int, epsilon: Fraction) -> Fraction:
    if n <= 0 or d <= 0 or k < 0 or k+2*(d-1)>n: raise ValueError("inadmissible")
    rate, delta = Fraction(k,n), Fraction(n+2-2*d,n)
    if epsilon > rate: raise ValueError("claimed rate floor is not met")
    assert epsilon <= delta
    return delta

